						if after := load(); after.Revision != before.Revision || !reflect.DeepEqual(after.StateBuckets, before.StateBuckets) {
							t.Fatal("conflicting contributor changed persisted count/results")
						}
					}
				}
				if scenario.until {
					publish("halt.requested", "", "", "")
				}
