				if err := selected.db.QueryRowContext(ctx, "SELECT COUNT(*) FROM events WHERE event_id=$1", late.ID()).Scan(&publications); err != nil {
					t.Fatal(err)
				}
				if after := load(); !reflect.DeepEqual(after, final) || publications != 0 {
