					t.Fatalf("%s terminal route replay under changed bundle: %v", verdict, err)
				}
				if len(bus.outbox) != beforeOutbox || len(bus.published) != beforePublished {
					t.Fatalf("%s terminal route replay duplicated work", verdict)
				}
			})
		}
